function y=golden_section2_3(re) 
r_img=xlsread('A题附件.xls','附件1'); 
high=1;low=0.5; 
range=high-low; 
lowm=high-0.618*range; 
highm=low+0.618*range; 
Rlm=sum(sum((r_img-lowm*re).^2));

28 

Rhm=sum(sum((r_img-highm*re).^2)); 
while (high-low>1e-8) 
 if Rlm>Rhm 
 low=lowm; 
 range=high-low; 
 lowm=high-0.618*range; 
 highm=low+0.618*range; 
 Rlm=Rhm; 
 Rhm=sum(sum((r_img-highm*re).^2)); 
 else 
 high=highm; 
 range=high-low; 
 lowm=high-0.618*range; 
 highm=low+0.618*range; 
 Rhm=Rlm; 
 Rlm=sum(sum((r_img-lowm*re).^2)); 
 end 
end 
y=(high+low)/2; 
end 
